test("synthetic Rust legacy-email fixtures authenticate and derive exact UTF8 SHA256", () => {
  const { createDecipheriv, createHash } = require("node:crypto");
  const rust = fs.readFileSync(path.join(__dirname, "../../../../../../../packages/openmates-browser-bindings/src/browser.rs"), "utf8");
