  const combined = Buffer.from(fixture, "base64");
  const decrypt = (keyBytes) => {
    const cipher = createDecipheriv("aes-256-gcm", keyBytes, combined.subarray(0, 12));
    cipher.setAuthTag(combined.subarray(-16));
    return Buffer.concat([cipher.update(combined.subarray(12, -16)), cipher.final()]);
  };
