async function readDispatcher(open) {
  globalThis.DedicatedWorkerGlobalScope=class {static [Symbol.hasInstance](value){return value===globalThis;}};
  const endpoint=new Endpoint();let freed=0,invalidated=0,active=false,calls=0;
  const rustStatus=()=>({...status,persisted:false,free(){}});
  const client={admitted_status:rustStatus,status(handle,generation){if(handle!==status.handle||generation!==1)throw "session_expired";return rustStatus();},
    async prepare_credentials(...args){calls++;active=true;try{return JSON.stringify(await open(...args,"prepare_credentials"));}finally{active=false;}},
    validate_credentials(...args){calls++;return JSON.stringify(open(...args,"validate_credentials"));},
    async open_chat(...args){calls++;active=true;try{return await open(...args);}finally{active=false;}},
    async reconnect_chat(...args){calls++;active=true;try{return await open(...args,"reconnect_chat");}finally{active=false;}},
    async read_saved_chat(...args){calls++;active=true;try{return JSON.stringify(await open(...args,"read_saved_chat"));}finally{active=false;}},
    invalidate(){assert.equal(active,false,'do not invalidate a borrowed async WASM client');invalidated++;},free(){assert.equal(active,false);freed++;}};
  const binding={PreparedBrowserProfile:{from_bytes(){return {free(){}};}},BrowserCoreClient:{async restore(){return client;}}};
  const locks={async request(_name,_options,callback){return callback();}};
  const dispose=installBrowserCoreWorker(endpoint,binding,{apiUrl:"https://api.example",appOrigin:"https://app.example",sessionId:"fixture"},locks);
  endpoint.receive({version:1,id:1,operation:"restore",key:await key(),profile,persistence:"memory_only"});
  for(let i=0;i<20&&!endpoint.sent.length;i++)await tick();assert.equal(endpoint.sent[0].ok,true);
  return {endpoint,dispose,get calls(){return calls;},get freed(){return freed;},get invalidated(){return invalidated;}};
}
