  const rustStatus=()=>{assert.equal(driverActive,false,"never reenter a mutably borrowed Client");return {...status,persisted:false,free(){}};};
  const control={publication_current(handle,generation,id){assert.deepEqual([handle,generation,id],[status.handle,1,operationId]);return !state.authorityRevoked;},cancel(handle,generation,id){assert.deepEqual([handle,generation,id],[status.handle,1,operationId]);cancelRequested++;},
    close(){if(!state.holdClose&&pollReject){const reject=pollReject;pollReject=null;releasePoll=null;reject(Error("PRIVATE_CLOSE"));}},free(){controlFreed++;}};
  const events={async next_event(handle,generation,id){assert.deepEqual([handle,generation,id],[status.handle,1,operationId]);assert.equal(pollActive,false);pollActive=true;
    try{return queue.length?queue.shift():await new Promise((resolve,reject)=>{releasePoll=resolve;pollReject=reject;});}finally{pollActive=false;}},
    free(){assert.equal(pollActive,false,"do not free borrowed event handle");eventFreed++;}};
