    prepare_send(handle,generation,chatId){assert.deepEqual([handle,generation,chatId],[status.handle,1,chat.id]);assert.equal(driverActive,false);
      return {operation_id:operationId,control:()=>control,take_events:()=>events,free(){preparedFreed++;}};},
    async send_saved(handle,generation,_prepared,text){assert.deepEqual([handle,generation],[status.handle,1]);assert.equal(typeof text,"string");starts++;driverActive=true;
      try{await new Promise(resolve=>{finishDriver=resolve;});}finally{driverActive=false;}},
    invalidate(){assert.equal(driverActive,false);invalidated++;},free(){assert.equal(driverActive,false);clientFreed++;}};
