test('WASM owner revocation reaches prepared terminal without a suspending close gap',()=>{
  const root=path.resolve(__dirname,'../../../../../../..');
  const socket=fs.readFileSync(path.join(root,'packages/openmates-rust/src/platform/browser_socket.rs'),'utf8');
  const body=socket.match(/pub\(crate\) async fn close\(&mut self, _: Option<CloseFrame>\) -> Result<\(\), Error>\s*\{([^{}]*)\}/)?.[1];
  assert.ok(body,'actual browser close must remain an auditable direct primitive');
  assert.equal(body.trim(),'self.socket.close().map_err(|_| Error::ConnectionClosed)');
  const send=fs.readFileSync(path.join(root,'packages/openmates-rust/src/client/send.rs'),'utf8');
  const tail=send.slice(send.indexOf('        let _ = ws.close(None).await;',send.indexOf('let result = self\n            .send_on_socket')));
  const returned=tail.slice(0,tail.indexOf('\n        result\n'));
  assert.ok(returned.length>0);assert.equal((returned.match(/\.await\b/g)||[]).length,1,'only immediate browser close may follow send result');
  const binding=fs.readFileSync(path.join(root,'packages/openmates-browser-bindings/src/browser.rs'),'utf8');
  const lane=binding.slice(binding.indexOf('let result = self.client.send_message'),binding.indexOf('prepared.finish(terminal);'));
  assert.ok(lane.length>0);assert.equal((lane.match(/\.await\b/g)||[]).length,1,'prepared terminal immediately follows shared send result');
});

import type { LocalReadPlan, SavedPageSelector } from "./protocol";
/** Explicit page-owned existing-key admission and bounded saved-chat retrieval.
 * This composes platform IO/lifetime adapters; Rust owns auth and all decryption.
 * No key export, enrollment, storage write, retry, implicit CLI credential or
 * legacy read fallback occurs here. The original browser persistence preference
 * remains evidence owned by the supplied source; Worker admission is memory-only.
 * Install only explicitly, before capture, and retain through final publication.
 */
import { bindProductionCoreInvalidations } from "./productionInvalidationBridge";
import { publishSelectedSavedChat, publishSelectedLocalSavedChat, publishSelectedCursorSavedChat, publishSelectedSavedChatPage, publishSelectedCheckpointSummary } from "./selectedSavedChat";
import type { SavedChatSelection } from "./selectedSavedChat";
import type { PriorProfileLifecycle } from "./platformLifecycle";
import type { BrowserCoreWorkerHost } from "./workerHost";
import type { ExistingProfileEvidence, SessionStatus, BrowserPersistence } from "./protocol";
import type { SavedChatReadback, LocalChatReadback, CheckpointPresentation } from "./savedReadProtocol";

export interface ExistingSavedChatProfile {
  readonly generation: number;
  readonly key: CryptoKey;
  readonly profile: Readonly<ExistingProfileEvidence>;
  readonly persistence: BrowserPersistence;
}
export interface ExistingSavedChatSources {
  capture(generation: number): Promise<ExistingSavedChatProfile>;
  assertCurrent(snapshot: ExistingSavedChatProfile): Promise<void>;
  /** Optional only because online reads need no local enumeration. */
  executeLocalReadPlan?(snapshot: ExistingSavedChatProfile, selected: Readonly<SavedChatSelection>, plan: LocalReadPlan, signal: AbortSignal): Promise<string>;
  readEncryptedRows?(selected: Readonly<SavedChatSelection>, signal: AbortSignal): Promise<unknown>;
}
export interface ProductionSavedChatSession {
  readonly status: Readonly<SessionStatus>;
  /** Consume the entire DTO synchronously; do not retain it for a later write. */
  publish(publish: (page: SavedChatReadback | LocalChatReadback) => void): Promise<void>;
  publishPage(selector: SavedPageSelector, publish: (page: SavedChatReadback | LocalChatReadback) => void): Promise<void>;
  publishCheckpointSummary(checkpointId:string,publish:(page:CheckpointPresentation)=>void):Promise<void>;
  close(): void;
}
export interface ProductionSavedChatSessionInput {
  expectedPrincipal: string; signal: AbortSignal; sources: ExistingSavedChatSources;
  currentSelection(): SavedChatSelection;
}
/** The app supplies its actual production Worker factory. The factory is owned,
 * never a transport/session credential and never selected through a global flag.
 */
export async function admitProductionSavedChatSession(input: ProductionSavedChatSessionInput & {
  lifecycle: PriorProfileLifecycle;
  page: Pick<Window, "addEventListener" | "removeEventListener">;
  createChannel(name: string): Pick<BroadcastChannel, "addEventListener" | "removeEventListener" | "close">;
  createWorker(signal: AbortSignal): Promise<{ host: BrowserCoreWorkerHost; close(): void }>;
}): Promise<ProductionSavedChatSession> {
  const lifetime = new AbortController();
  let closed = false, busy = false;
  let witness: ExistingSavedChatProfile | null = null;
  let worker: Awaited<ReturnType<typeof input.createWorker>> | null = null;
  let releaseInvalidations: (() => void) | null = null;
  const close = () => {
    if (closed) return;
    closed = true; witness = null; lifetime.abort();
    input.signal.removeEventListener("abort", close);
    try { releaseInvalidations?.(); } finally { worker?.close(); }
  };
  input.signal.addEventListener("abort", close, { once: true });
  try {
    if (input.signal.aborted) throw new Error("cancelled");
    releaseInvalidations = bindProductionCoreInvalidations({ ...input, host: { close } });
    const owned = await input.createWorker(lifetime.signal);
    worker = owned;
    // A factory may finish after the Page lifetime was revoked while loading.
    if (closed || lifetime.signal.aborted) { owned.close(); throw new Error("cancelled"); }
    witness = await input.sources.capture(input.lifecycle.current());
    if (closed || lifetime.signal.aborted) { witness = null; throw new Error("cancelled"); }
    const current = () => {
      const prior = witness;
      if (!prior || closed || lifetime.signal.aborted || input.lifecycle.current() !== prior.generation
        || prior.profile.principal !== input.expectedPrincipal
        || input.currentSelection().ownerId !== input.expectedPrincipal) throw new Error("invalidated_snapshot");
    };
    current(); await input.sources.assertCurrent(witness!); current();
    const response = await owned.host.request({ operation: "restore_existing", key: witness!.key,
      profile: { ...witness!.profile }, persistence: "memory_only" }, lifetime.signal);
    current(); await input.sources.assertCurrent(witness!); current();
    if (!response.ok || !response.status || response.status.principal !== input.expectedPrincipal
