                        ..ClientOptions::default()
                    },
                )
                .unwrap();
                let lifecycle = client.lifecycle();
                assert_eq!(lifecycle["client_type"], identity.header());
                assert_eq!(lifecycle["is_foreground"], true);
                assert_eq!(
                    lifecycle["interactive"],
                    identity == ClientIdentity::Cli && interactive
                );
            }
        }
    }

    #[tokio::test]
    async fn noninteractive_chat_sync_receives_foreground_recovery_fence_in_either_order() {
        for (identity, recovery_first) in
            [(ClientIdentity::Rust, true), (ClientIdentity::Cli, false)]
        {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
            let address = listener.local_addr().unwrap();
            let server = tokio::spawn(async move {
                let (mut http, _) = listener.accept().await.unwrap();
                let mut request = Vec::new();
                loop {
                    let mut buffer = [0; 2048];
                    let size = http.read(&mut buffer).await.unwrap();
                    assert!(size > 0);
                    request.extend_from_slice(&buffer[..size]);
                    assert!(request.len() < 16_384);
                    if let Some(end) = request.windows(4).position(|p| p == b"\r\n\r\n") {
                        let headers = std::str::from_utf8(&request[..end]).unwrap();
                        let length = headers
                            .lines()
                            .find_map(|line| {
                                line.to_ascii_lowercase()
                                    .strip_prefix("content-length:")
                                    .map(|v| v.trim().parse::<usize>().unwrap())
                            })
                            .unwrap_or(0);
                        if request.len() >= end + 4 + length {
                            assert_eq!(
                                headers.lines().next().unwrap(),
                                "POST /v1/auth/session HTTP/1.1"
                            );
                            break;
                        }
                    }
                }
                let body = json!({"success":true,"ws_token":"synthetic-token","user":{"id":"synthetic-owner"}}).to_string();
                http.write_all(format!("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}", body.len()).as_bytes()).await.unwrap();
                drop(http);
                let (stream, _) = listener.accept().await.unwrap();
                let mut ws = tokio_tungstenite::accept_async(stream).await.unwrap();
                let lifecycle: Value =
                    serde_json::from_str(&ws.next().await.unwrap().unwrap().into_text().unwrap())
                        .unwrap();
                assert_eq!(lifecycle["type"], "native_client_lifecycle");
                assert_eq!(lifecycle["payload"]["is_foreground"], true);
                assert_eq!(lifecycle["payload"]["interactive"], false);
                assert_eq!(lifecycle["payload"]["client_type"], identity.header());
                let sync: Value =
                    serde_json::from_str(&ws.next().await.unwrap().unwrap().into_text().unwrap())
                        .unwrap();
                assert_eq!(sync["type"], "phased_sync_request");
                assert_eq!(sync["payload"]["phase"], "all");
                ws.send(Message::Text(
                    json!({"type":"phase_2_last_20_chats_ready","payload":{"chats":[]}})
                        .to_string()
                        .into(),
                ))
                .await
                .unwrap();
                let recovery = json!({"type":"recovery_outputs_discovery_complete","payload":{"status":"completed"}});
                let sync = json!({"type":"phased_sync_complete","payload":{"phase":"all"}});
                // The real backend starts this discovery only for foreground
                // sockets. Preserve both terminal fences rather than skipping
                // recovery when the SDK caller is not a human viewer.
                for frame in if recovery_first {
                    [recovery, sync]
                } else {
                    [sync, recovery]
                } {
                    ws.send(Message::Text(frame.to_string().into()))
                        .await
                        .unwrap();
                }
                assert!(matches!(
                    ws.next().await.unwrap().unwrap(),
                    Message::Close(_)
                ));
            });
            let base = format!("http://{address}");
            let mut session = super::sdk_boundary_tests::session();
            session.api_url = base.clone();
            let mut client = Client::with_options(
                &base,
                Some(session),
                ClientOptions {
                    identity,
                    ..ClientOptions::default()
                },
            )
            .unwrap();
            let result = crate::platform::time::timeout(
                Duration::from_secs(3),
                client.list(Workspace::Chats),
            )
            .await
            .unwrap()
            .unwrap();
            assert!(result.is_empty());
            server.await.unwrap();
        }
    }
}

pub use monitor::{BrowserMetadataMonitorRefresh, BrowserMetadataMonitorPublication};

pub use monitor::BrowserIncomingCachePublication;

//! One authenticated encrypted viewing page, never a complete-history snapshot.
//! The existing Client owns metadata authorization, cookie transport and keys.
//! Cursors are selectors bound to this live Client/context, not authority leases.
//! Page-local message mappings restore known PII; omitted mappings stay literal.
//! No page rows, inventory proofs or recovery jobs enter the complete cache.
use super::plaintext::{Plain, replace_text};
use super::{
    sync::{decode_chat_message, decrypt_optional},
    *,
};
use serde::{Deserialize, Serialize};

/// Saved-message read IDs are nonempty opaque UTF-8 strings, never authority.
/// Complete row/packet/window byte budgets bound resources separately; there is
/// no universal per-ID maximum across maintained server and local stores.
/// Preserve exact bytes/case/control characters; never trim or normalize IDs.
/// Canonical Chat UUID, owner/scope, ordering and ciphertext guards are separate.
pub fn valid_message_id(value: &str) -> bool {
    !value.is_empty()
}

/// Canonical server row aliases: logical client/message aliases must agree;
/// an independent database `id` alias can differ. Empty/null legacy aliases
/// fall through exactly as the deployed nonempty client/message/id preference.
/// Nonstring aliases and conflicting logical aliases are refused, not repaired.
pub(super) fn server_message_id(row: &Value) -> Result<&str> {
    let mut selected = None;
    for field in ["client_message_id", "message_id", "id"] {
        let Some(value) = row.get(field).filter(|value| !value.is_null()) else {
            continue;
        };
        let value = value.as_str().ok_or(Error::Protocol)?;
        if value.is_empty() {
            continue;
        }
        if !valid_message_id(value) {
            return Err(Error::Protocol);
        }
        if field == "message_id"
            && row.get("client_message_id").and_then(Value::as_str)
                .filter(|client| !client.is_empty()).is_some_and(|client| client != value)
        {
            return Err(Error::Protocol);
        }
        if selected.is_none() {
            selected = Some(value);
        }
    }
    selected.ok_or(Error::Protocol)
}

pub(super) const MAX_MESSAGES: usize = 20;
pub(super) const MAX_MESSAGE_BYTES: usize = 256 * 1024;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum MessageWindowDirection {
    Latest,
    Before,
    After,
    Around,
}

impl Default for MessageWindowDirection {
    fn default() -> Self {
        Self::Latest
    }
}

/// A live-context paging selector. Reimport/reset/workspace changes invalidate it.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct MessageWindowCursor {
    pub chat_id: String,
    pub scope: String,
    pub created_at: i64,
    pub message_id: String,
}
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct MessageWindowOptions {
    #[serde(default)]
    pub direction: MessageWindowDirection,
    #[serde(default = "default_limit")]
    pub limit: usize,
    #[serde(default)]
    pub cursor: Option<MessageWindowCursor>,
    #[serde(default)]
    pub anchor_message_id: Option<String>,
    #[serde(default = "default_compression")]
    pub respect_compression_boundary: bool,
}
fn default_limit() -> usize {
    MAX_MESSAGES
}
fn default_compression() -> bool {
    true
}
impl Default for MessageWindowOptions {
    fn default() -> Self {
        Self {
            direction: MessageWindowDirection::Latest,
            limit: MAX_MESSAGES,
            cursor: None,
            anchor_message_id: None,
            respect_compression_boundary: true,
        }
    }
}
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ChatMessageWindow {
    pub chat: Chat,
    pub has_more_before: bool,
    pub has_more_after: bool,
    pub anchor_found: bool,
    pub start_cursor: Option<MessageWindowCursor>,
    pub end_cursor: Option<MessageWindowCursor>,
    pub server_message_count: Option<u64>,
    pub messages_version: Option<u64>,
    pub oversized_message: bool,
    pub oversized_message_cursor: Option<MessageWindowCursor>,
    pub payload_bytes: usize,
    /// Always "page_local"; no cumulative mapping endpoint exists.
    pub pii_restoration: String,
    /// Always false: even a terminal page does not replace complete cache state.
    pub history_complete: bool,
}
impl MessageWindowOptions {
    pub(super) fn validate(&self, id: &str, scope: &str) -> Result<()> {
        if super::monitor::cached_view::bounded_bytes(self, MAX_MESSAGE_BYTES).is_none() {
            return Err(Error::Invalid("Message window selector exceeds its packet budget."));
        }
        if !(1..=MAX_MESSAGES).contains(&self.limit) {
            return Err(Error::Invalid(
                "Message window limit must be between 1 and 20.",
            ));
        }
        let paging = matches!(
            self.direction,
            MessageWindowDirection::Before | MessageWindowDirection::After
        );
        if paging != self.cursor.is_some()
            || (self.direction == MessageWindowDirection::Around)
                != self.anchor_message_id.is_some()
        {
            return Err(Error::Invalid(
                "Message window requires its exact direction cursor or anchor.",
            ));
        }
        if let Some(c) = &self.cursor {
            if c.created_at < 0
                || !valid_message_id(&c.message_id)
                || c.scope.len() != 64
                || !c.scope.bytes().all(|v| v.is_ascii_hexdigit())
            {
                return Err(Error::Invalid("Invalid message window cursor."));
            }
            if c.chat_id != id || c.scope != scope {
                return Err(Error::Conflict);
            }
        }
        if self
            .anchor_message_id
            .as_ref()
            .is_some_and(|v| !valid_message_id(v))
        {
            return Err(Error::Invalid("Invalid message window anchor."));
        }
        Ok(())
    }
}
fn cursor(page: &Value, name: &str, id: &str, scope: &str) -> Result<Option<MessageWindowCursor>> {
    let Some(value) = page.get(name).filter(|v| !v.is_null()) else {
        return Ok(None);
    };
    let created_at = value
        .get("created_at")
        .and_then(Value::as_i64)
        .filter(|v| *v >= 0)
        .ok_or(Error::Protocol)?;
    let message_id = required(value, "message_id")?;
    if !valid_message_id(message_id) { return Err(Error::Protocol); }
    Ok(Some(MessageWindowCursor {
        chat_id: id.into(),
        scope: scope.into(),
        created_at,
        message_id: message_id.into(),
    }))
}
fn boolean(page: &Value, field: &str) -> Result<bool> {
    page.get(field)
        .and_then(Value::as_bool)
        .ok_or(Error::Protocol)
}
fn optional_count(page: &Value, field: &str) -> Result<Option<u64>> {
    match page.get(field).filter(|v| !v.is_null()) {
        None => Ok(None),
        Some(v) => v.as_u64().map(Some).ok_or(Error::Protocol),
    }
}
// Around readback must attest the requested row, not merely plausible cursors.
// Database IDs are valid lookup aliases; cursor/output IDs remain canonical.
fn validate_anchor(
    options: &MessageWindowOptions,
    rows: &[Value],
    found: bool,
    oversized: bool,
    oversized_cursor: Option<&MessageWindowCursor>,
) -> Result<()> {
    if options.direction != MessageWindowDirection::Around {
        return Ok(());
    }
    let anchor = options
        .anchor_message_id
        .as_deref()
        .ok_or(Error::Protocol)?;
    if !found {
        return if rows.is_empty() && !oversized {
            Ok(())
        } else {
            Err(Error::Protocol)
        };
    }
    if rows.iter().any(|row| {
        ["id", "client_message_id", "message_id"]
            .into_iter()
            .any(|name| row.get(name).and_then(Value::as_str) == Some(anchor))
    }) {
        return Ok(());
    }
    // A byte-oversized anchor is deliberately omitted and exposes only its
    // stable cursor. Without a row, an unproven DB-ID alias cannot be inferred.
    if rows.is_empty() && oversized && oversized_cursor.is_some_and(|c| c.message_id == anchor) {
        return Ok(());
    }
    Err(Error::Protocol)
}

impl Client {
    pub(super) fn message_window_scope(&self) -> Result<String> {
        self.require_credentials()?;
        Ok(sha256(&serde_json::to_string(&(
            &self.message_window_nonce,
            self.generation,
            self.team()?,
        ))?))
    }
    // The sole plaintext publication boundary; runs after decoding/restoration.
    fn publish_message_window(
        &self,
        scope: &str,
        window: ChatMessageWindow,
    ) -> Result<ChatMessageWindow> {
        let window = Plain::new(window);
        if self.operation_cancel.is_cancelled() {
            return Err(Error::Cancelled);
        }
        if self.message_window_scope()? != scope {
            return Err(Error::Conflict);
        }
        Ok(window.into_inner())
    }
    fn publish_message_window_with_capability(
        &self,
        scope: &str,
        crypto_scope: &super::sync_capability::AsyncCryptoScope,
        window: ChatMessageWindow,
    ) -> Result<ChatMessageWindow> {
        let window = Plain::new(window);
        crypto_scope.check(self)?;
        self.require_canonical_read_profile()?;
        self.publish_message_window(scope, window.into_inner())
    }
    /// Fetch/decrypt one currently authorized server page. Never synchronizes,
    /// claims recovery work, reads older pages or promotes partial cache rows.
    pub async fn chat_message_window(
        &mut self,
        id: &str,
        options: MessageWindowOptions,
    ) -> Result<ChatMessageWindow> {
        Ok(self.read_message_page(id, options, false).await?.window)
    }
    pub(super) async fn read_message_page(
        &mut self,
        id: &str,
        options: MessageWindowOptions,
        stored: bool,
    ) -> Result<MessagePageData> {
        self.read_message_page_inner(id,options,stored,false).await
    }
    pub(super) async fn read_browser_cache_message_page(&mut self,id:&str,options:MessageWindowOptions)->Result<MessagePageData>{
        self.read_message_page_inner(id,options,false,true).await
    }
    async fn read_message_page_inner(&mut self,id:&str,options:MessageWindowOptions,stored:bool,capture_browser:bool)->Result<MessagePageData>{
        self.require_canonical_read_profile()?;
        uuid::Uuid::parse_str(id).map_err(|_| Error::Invalid("A full chat ID is required."))?;
        if self.is_ephemeral_chat(id) {
            return Err(Error::Invalid("Volatile chat history has no server page."));
        }
        if self.operation_cancel.is_cancelled() {
            return Err(Error::Cancelled);
        }
        let crypto_scope = super::sync_capability::AsyncCryptoScope::begin(self)?;
        let scope = self.message_window_scope()?;
        options.validate(id, &scope)?;
        let metadata = self
            .request_chat_metadata(id)
            .await?
            .ok_or(Error::Forbidden)?;
        if self.operation_cancel.is_cancelled() {
            return Err(Error::Cancelled);
        }
        let rows = metadata["chats"].as_array().ok_or(Error::Protocol)?;
        if rows.len() != 1 || text(&rows[0], "id") != id {
            return Err(Error::Forbidden);
        }
        crypto_scope.check(self)?;
        let row = &rows[0];
        if capture_browser {self.browser_message_cache_metadata_guard(row,id)?;}
        let metadata_stamp = sha256(&serde_json::to_string(row)?);
        // Reuse the same fresh Team/direct wrapping-key policy as full open.
        let wrapping = self.wrapping_capability().await?;
        if text(row, "chat_visibility") == "direct" {
            self.load_direct_identity().await?;
        }
        let key = self.chat_key_with_capability(row, &wrapping).await?;
        let mut item = Plain::new(self.chat_item(row, &key)?);
        let mut url = self.url(&format!("/v1/chats/{}/messages/window", segment(id)))?;
        {
            let mut query = url.query_pairs_mut();
            let direction = match options.direction {
                MessageWindowDirection::Latest => "latest",
                MessageWindowDirection::Before => "before",
                MessageWindowDirection::After => "after",
                MessageWindowDirection::Around => "around",
            };
            query
                .append_pair("direction", direction)
                .append_pair("limit", &options.limit.to_string())
                .append_pair(
                    "respect_compression_boundary",
                    if options.respect_compression_boundary {
                        "true"
                    } else {
                        "false"
                    },
                );
            if let Some(c) = &options.cursor {
                let prefix = if options.direction == MessageWindowDirection::Before {
                    "before"
                } else {
                    "after"
                };
                query
                    .append_pair(&format!("{prefix}_timestamp"), &c.created_at.to_string())
                    .append_pair(&format!("{prefix}_message_id"), &c.message_id);
            }
            if let Some(anchor) = &options.anchor_message_id {
                query.append_pair("anchor_message_id", anchor);
            }
        }
        let path = self.scoped(&format!("{}?{}", url.path(), url.query().unwrap_or("")))?;
        let page = self.request(Method::GET, &path, None).await?;
        crypto_scope.check(self)?;
        if self.operation_cancel.is_cancelled() {
            return Err(Error::Cancelled);
        }
        if self.message_window_scope()? != scope {
            return Err(Error::Conflict);
        }
        if page
            .get("chat_id")
            .and_then(Value::as_str)
            .is_some_and(|v| v != id)
        {
            return Err(Error::Forbidden);
        }
        // Aggregated saved reads must not join pages across a moving read
        // boundary/version/count. v1 ignores this private stamp as before.
        let metadata_stamp = if stored {
            sha256(&serde_json::to_string(&json!([
                metadata_stamp,
                page.get("messages_v"),
                page.get("server_message_count"),
                page.get("compression_boundary_timestamp"),
            ]))?)
        } else {
            metadata_stamp
        };
        let input = page["messages"].as_array().ok_or(Error::Protocol)?;
        if input.len() > options.limit || input.len() > MAX_MESSAGES {
            return Err(Error::Protocol);
        }
        let mut encrypted = PageCiphertextRows {values:vec![],guarded:capture_browser};
        let mut messages = Plain::new(Vec::<Message>::new());
        let mut seen = std::collections::HashSet::new();
        let mut bytes = 0usize;
        let mut previous = None;
        for raw in input {
            let raw: Value = if let Some(s) = raw.as_str() {
                serde_json::from_str(s)?
            } else {
                raw.clone()
            };
            bytes = bytes
                .checked_add(
                    crate::client::monitor::cached_view::bounded_bytes(&raw, usize::MAX)
                        .ok_or(Error::Protocol)?,
                )
                .ok_or(Error::Protocol)?;
            if bytes > MAX_MESSAGE_BYTES {
                return Err(Error::Protocol);
            }
            server_message_id(&raw)?;
            let (raw, message) = decode_chat_message(&raw, id, &key, &mut seen)?;
            let message = Plain::new(message);
            if !valid_message_id(&message.id) { return Err(Error::Protocol); }
            let timestamp = raw
                .get("created_at")
                .and_then(Value::as_i64)
                .filter(|v| *v >= 0)
                .ok_or(Error::Protocol)?;
            let position = (timestamp, message.id.clone());
            if previous.as_ref().is_some_and(|p| p >= &position) {
                return Err(Error::Protocol);
            }
            if let Some(c) = &options.cursor {
                let boundary = (c.created_at, c.message_id.clone());
                if (options.direction == MessageWindowDirection::Before && position >= boundary)
                    || (options.direction == MessageWindowDirection::After && position <= boundary)
                {
                    return Err(Error::Protocol);
                }
            }
            previous = Some(position);
            encrypted.push(raw);
            messages.push(message.into_inner());
        }
        let has_more_before = boolean(&page, "has_more_before")?;
        let has_more_after = boolean(&page, "has_more_after")?;
        let start_cursor = cursor(&page, "start_cursor", id, &scope)?;
        let end_cursor = cursor(&page, "end_cursor", id, &scope)?;
        for (c, raw, message) in [
            (start_cursor.as_ref(), encrypted.first(), messages.first()),
            (end_cursor.as_ref(), encrypted.last(), messages.last()),
        ] {
            match (c, raw, message) {
                (Some(c), Some(raw), Some(message))
                    if c.created_at == raw["created_at"].as_i64().ok_or(Error::Protocol)?
                        && c.message_id == message.id =>
                {
                    ()
                }
                (None, None, None) => (),
                _ => return Err(Error::Protocol),
            }
        }
        let oversized_message = boolean(&page, "oversized_message")?;
        let oversized_message_cursor = cursor(&page, "oversized_message_cursor", id, &scope)?;
        if oversized_message != oversized_message_cursor.is_some() {
            return Err(Error::Protocol);
        }
        if (has_more_before && start_cursor.is_none() || has_more_after && end_cursor.is_none())
            && !oversized_message
        {
            return Err(Error::Protocol);
        }
        let anchor_found = boolean(&page, "anchor_found")?;
        validate_anchor(
            &options,
            &encrypted,
            anchor_found,
            oversized_message,
            oversized_message_cursor.as_ref(),
        )?;
        let mut mappings = Plain::new(Vec::<Value>::new());
        let mut per_message = Plain::new(std::collections::BTreeMap::<String, Vec<Value>>::new());
        for (raw, message) in encrypted.iter().zip(messages.iter()) {
            // Match bounded web viewing: only loaded user-message maps apply.
            if !stored && text(raw, "role") != "user" {
                continue;
            }
            let value =
                zeroize::Zeroizing::new(decrypt_optional(raw, "encrypted_pii_mappings", &key)?);
            if !value.is_empty() {
                let values = Plain::new(serde_json::from_str::<Vec<Value>>(&value)?);
                if text(raw, "role") == "user" {
                    mappings.extend(values.iter().cloned());
                }
                if stored {
                    per_message.insert(message.id.clone(), values.into_inner());
                }
            } else if stored {
                if let Some(ciphertext) = raw.get("encrypted_pii_mappings").and_then(Value::as_str)
                {
                    // Match raw/JSON field presence: an empty encrypted field
                    // projects [], but nonempty invalid decrypted JSON refuses.
                    let values = Plain::new(if ciphertext.is_empty() {
                        vec![]
                    } else {
                        serde_json::from_str::<Vec<Value>>(&value)?
                    });
                    per_message.insert(message.id.clone(), values.into_inner());
                }
            }
        }
        for message in messages.iter_mut().filter(|_| !stored) {
            let restored = crate::privacy::restore_page(&message.content, &mappings)?;
            replace_text(&mut message.content, restored);
            let restored = crate::privacy::restore_page(&message.thinking, &mappings)?;
            replace_text(&mut message.thinking, restored);
        }
        if optional_count(&page, "payload_bytes")? != Some(bytes as u64) {
            return Err(Error::Protocol);
        }
        if self.operation_cancel.is_cancelled() {
            return Err(Error::Cancelled);
        }
        let chat_metadata = Plain::new(if stored {
            Some(super::saved_chat_read::metadata::chat(row, id, &key)?)
        } else {
            None
        });
        let mut message_metadata =
            Plain::new(Vec::<super::saved_chat_read::SavedChatMessageMetadata>::new());
        if stored {
            for (raw, message) in encrypted.iter().zip(messages.iter()) {
                message_metadata.push(super::saved_chat_read::metadata::message(
                    raw, message, id, &key,
                )?);
            }
        }
        let server_message_count = optional_count(&page, "server_message_count")?;
        let messages_version = optional_count(&page, "messages_v")?;
        // Exact raw wire data is retained ONLY for the explicit cache path.
        // Ordinary/native reads receive None with no extra clone/allocation.
        let incoming = if capture_browser {
            if super::monitor::cached_view::bounded_bytes(&(row,&encrypted.values),MAX_MESSAGE_BYTES).is_none(){return Err(Error::Protocol);}
            Some(BrowserIncomingMessagePage {metadata:Plain::new(row.clone()),messages:Plain::new(std::mem::take(&mut encrypted.values)),key})
        } else {None};
        let window = self.publish_message_window_with_capability(
            &scope,
            &crypto_scope,
            ChatMessageWindow {
                chat: Chat {
                    id: id.into(),
                    title: std::mem::take(&mut item.title),
                    category: std::mem::take(&mut item.category),
                    messages: messages.into_inner(),
                },
                has_more_before,
                has_more_after,
                anchor_found,
                start_cursor,
                end_cursor,
                server_message_count,
                messages_version,
                oversized_message,
                oversized_message_cursor,
                payload_bytes: bytes,
                pii_restoration: "page_local".into(),
                history_complete: false,
            },
        )?;
        Ok(MessagePageData {
            incoming,
            window,
            mappings: per_message.into_inner(),
            metadata_stamp,
            chat_metadata: chat_metadata.into_inner(),
            message_metadata: message_metadata.into_inner(),
        })
    }
}

pub(super) struct MessagePageData {
    pub(super) incoming:Option<BrowserIncomingMessagePage>,
    pub window: ChatMessageWindow,
    pub mappings: std::collections::BTreeMap<String, Vec<Value>>,
