// No serialization, cloning, master extraction or reusable auth proof exists.
pub(super) struct BrowserIncomingMessagePage {
 pub(super) metadata:Plain<Value>,pub(super) messages:Plain<Vec<Value>>,pub(super) key:Key,
}
