        let old = watch(&client);
        let read = ProjectTaskWatchRead {
            authority: old.binding.authority.clone(),
            watch_lifetime: old.lifetime.clone(),
            sequence: 0,
            identity: old.identity.clone(),
            scope: Box::new(old.scope().clone()),
