pub(crate) fn decode_input<T: serde::de::DeserializeOwned>(encoded: String) -> Result<T> {
    let encoded = Zeroizing::new(encoded);
    if encoded.len() > 1024 * 1024 {
        return Err(Error::Invalid("Work input exceeds the supported size.").into());
    }
    serde_json::from_str(&encoded).map_err(|_| Error::Invalid("Invalid typed work input.").into())
}

/// Explicit caller policy. Credentials and keys deliberately have no Debug.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BindingOptions {
    pub api_url: String,
    pub app_url: Option<String>,
    pub enhanced_privacy: bool,
    pub allow_private_operations: bool,
}
#[derive(Serialize)]
pub struct BindingError {
    pub code: &'static str,
    pub message: &'static str,
}
impl BindingError {
    pub fn json(&self) -> String {
        serde_json::to_string(self).unwrap_or_else(|_| {
            r#"{"code":"protocol","message":"The native operation failed."}"#.into()
        })
    }
}
impl From<Error> for BindingError {
    fn from(error: Error) -> Self {
        let (code, message) = match error {
            Error::Invalid(message) => ("invalid_argument", message),
            Error::Crypto => ("crypto", "Encrypted data could not be authenticated."),
            Error::Authentication => (
                "authentication",
                "Sign-in is required or credentials were rejected.",
            ),
            Error::TwoFactorRequired => (
                "two_factor_required",
                "Enter your two-factor authentication code.",
            ),
            Error::SignupRequired => ("signup_required", "Create an account to continue."),
            Error::Unavailable { .. } => ("unavailable", "The requested operation is unavailable."),
            Error::Locked => ("locked", "The credential store is locked."),
            Error::Offline => ("offline", "The service could not be reached."),
            Error::Forbidden => (
                "forbidden",
                "The operation is not allowed by the account or explicit policy.",
            ),
            Error::Expired => ("expired", "The session expired."),
            Error::Cancelled => ("cancelled", "The operation was cancelled."),
            Error::Io => ("io", "The local operation could not be completed."),
            Error::Protocol => ("protocol", "The service returned an invalid response."),
            Error::Conflict => (
                "conflict",
                "Another operation or state change conflicts with this request.",
            ),
        };
        Self { code, message }
    }
}
type Result<T> = std::result::Result<T, BindingError>;
type ConsentResponse = (String, Vec<String>);
type ConsentSender = mpsc::UnboundedSender<ConsentResponse>;
struct Active {
    id: String,
    cancel: CancellationToken,
}
struct Events {
    id: String,
    receiver: mpsc::Receiver<Value>,
}
struct WorkflowWait {
    run: String,
    cancel: CancellationToken,
}
struct State {
    client: AsyncMutex<Client>,
    endpoint: String,
    active: Mutex<Option<Active>>,
    events: AsyncMutex<Option<Events>>,
    consent: Mutex<Option<ConsentSender>>,
    pending_consent: Mutex<BTreeMap<String, BTreeSet<String>>>,
    closed: AtomicBool,
    work_operations: Mutex<BTreeMap<String, CancellationToken>>,
    identity_epoch: AtomicU64,
    workflow_waits: Mutex<BTreeMap<String, WorkflowWait>>,
    project_task_watches: project_task_watch::Registry,
    essential: essential::Registry,
    #[cfg(test)]
    draft_return_barrier: Mutex<Option<Arc<drafts::DraftReturnBarrier>>>,
    #[cfg(test)]
    saved_read_return_barrier: Mutex<Option<Arc<saved_read::SavedReadReturnBarrier>>>,
    #[cfg(test)]
    work_return_barrier: Mutex<Option<Arc<work::WorkReturnBarrier>>>,
}
/// Cloneable handle; every async SDK operation runs to its transaction boundary
/// even if a foreign-language Future is abandoned. Cancellation is cooperative.
#[derive(Clone)]
pub struct SessionBridge {
    state: Arc<State>,
}
impl SessionBridge {
    pub fn new(options_json: &str) -> Result<Self> {
        Self::with_identity(options_json, ClientIdentity::Rust)
    }
    pub fn with_identity(options_json: &str, identity: ClientIdentity) -> Result<Self> {
        let options: BindingOptions = serde_json::from_str(options_json)
            .map_err(|_| BindingError::from(Error::Invalid("options")))?;
        let privacy = PrivacyOptions {
            enhanced: options.enhanced_privacy,
        };
        privacy.verify().map_err(BindingError::from)?;
        let allow = options.allow_private_operations;
        let client = Client::with_options(
            &options.api_url,
            None,
            ClientOptions {
                identity,
                interactive: false,
                app_url: options.app_url,
                privacy,
                private_operation_gate: Some(Arc::new(move || {
                    if allow { Ok(()) } else { Err(Error::Forbidden) }
                })),
            },
        )
        .map_err(BindingError::from)?;
        Ok(Self {
            state: Arc::new(State {
                client: AsyncMutex::new(client),
                endpoint: options.api_url,
                active: Mutex::new(None),
                events: AsyncMutex::new(None),
                consent: Mutex::new(None),
                pending_consent: Mutex::new(BTreeMap::new()),
                closed: AtomicBool::new(false),
                work_operations: Mutex::new(BTreeMap::new()),
                identity_epoch: AtomicU64::new(0),
                workflow_waits: Mutex::new(BTreeMap::new()),
                project_task_watches: project_task_watch::Registry::default(),
                essential: essential::Registry::default(),
                #[cfg(test)]
                draft_return_barrier: Mutex::new(None),
                #[cfg(test)]
                saved_read_return_barrier: Mutex::new(None),
                #[cfg(test)]
                work_return_barrier: Mutex::new(None),
            }),
        })
    }
    fn available(&self) -> Result<()> {
        if self.state.closed.load(Ordering::Acquire) {
            Err(Error::Cancelled.into())
        } else {
            Ok(())
        }
    }
    async fn live_client(state: &State) -> Result<tokio::sync::MutexGuard<'_, Client>> {
        let client = state.client.lock().await;
        if state.closed.load(Ordering::Acquire) {
            Err(Error::Cancelled.into())
        } else {
            Ok(client)
        }
    }
    async fn transaction<T, F>(&self, future: F) -> Result<T>
    where
        T: Send + 'static,
        F: Future<Output = Result<T>> + Send + 'static,
    {
        self.available()?;
        // Dropping a foreign future detaches this task; it never drops a
        // credential rotation or committed HTTP operation partway through.
        tokio::spawn(future)
            .await
            .map_err(|_| BindingError::from(Error::Protocol))?
    }
    pub async fn login_password(
        &self,
        email: String,
        password: String,
        tfa: Option<String>,
    ) -> Result<String> {
        self.login_password_with_options(email,password,tfa,openmates_sdk::PasswordLoginOptions::default()).await
    }
    pub async fn login_password_with_options(
        &self, email: String, password: String, tfa: Option<String>,
        options: openmates_sdk::PasswordLoginOptions,
    ) -> Result<String> {
        let state = self.state.clone();
        let email = Zeroizing::new(email);
        self.state.essential.close_all();
        self.state.project_task_watches.close_all();
        let password = Zeroizing::new(password);
        let tfa = tfa.map(Zeroizing::new);
        self.transaction(async move {
            let mut client = Self::live_client(&state).await?;
            client
                .login_password_with_options(&email, &password, tfa.as_ref().map(|v| v.as_str()), options)
                .await
                .map_err(BindingError::from)?;
            state.identity_epoch.fetch_add(1, Ordering::AcqRel);
            serde_json::to_string(client.user()).map_err(|_| Error::Protocol.into())
        })
        .await
    }
    pub async fn import_session(&self, session_json: String) -> Result<()> {
        let encoded = Zeroizing::new(session_json);
        if encoded.len() > 1024 * 1024 {
            return Err(Error::Invalid("session").into());
        }
        let session: Session = serde_json::from_str(&encoded)
            .map_err(|_| BindingError::from(Error::Invalid("session")))?;
        self.state.essential.close_all();
        self.state.project_task_watches.close_all();
        let state = self.state.clone();
        self.transaction(async move {
            let mut client = Self::live_client(&state).await?;
            client
                .reset(&state.endpoint, Some(session))
                .map_err(BindingError::from)?;
            state.identity_epoch.fetch_add(1, Ordering::AcqRel);
            Ok(())
        })
        .await
    }
    pub async fn export_session(&self, include_secrets: bool) -> Result<String> {
        if !include_secrets {
            return Err(Error::Forbidden.into());
        }
        let state = self.state.clone();
        self.transaction(async move {
            let client = Self::live_client(&state).await?;
            let snapshot = client
                .credential_snapshot()
                .ok_or(Error::Authentication)
                .map_err(BindingError::from)?;
            serde_json::to_string(&json!({"revision":snapshot.revision,"session":snapshot.session}))
                .map_err(|_| Error::Protocol.into())
        })
        .await
    }
    pub async fn validate_session(&self) -> Result<()> {
        let state = self.state.clone();
        self.transaction(async move {
            Self::live_client(&state)
                .await?
                .validate_session()
                .await
                .map_err(BindingError::from)
        })
        .await
    }
    pub async fn list(&self, workspace: String) -> Result<String> {
        let workspace: Workspace = serde_json::from_value(Value::String(workspace))
            .map_err(|_| BindingError::from(Error::Invalid("workspace")))?;
        let state = self.state.clone();
        self.transaction(async move {
            let items = Self::live_client(&state)
                .await?
                .list(workspace)
                .await
                .map_err(BindingError::from)?;
            serde_json::to_string(&items).map_err(|_| Error::Protocol.into())
        })
        .await
    }
    pub async fn open_chat(&self, id: String) -> Result<String> {
        self.full_chat_read_transaction(id).await
    }
    pub async fn set_team(&self, id: Option<String>) -> Result<()> {
        self.state.essential.close_all();
        self.state.project_task_watches.close_all();
        let state = self.state.clone();
        self.transaction(async move {
            Self::live_client(&state)
                .await?
                .set_team(id.as_deref())
                .map_err(BindingError::from)
        })
        .await
    }
    pub fn cancel(&self) -> Result<()> {
        self.state.essential.close_all();
        self.state.project_task_watches.close_all();
        for token in self
            .state
            .work_operations
            .lock()
            .map_err(|_| BindingError::from(Error::Protocol))?
            .values()
        {
            token.cancel();
        }
        if let Some(active) = self
            .state
            .active
            .lock()
            .map_err(|_| BindingError::from(Error::Protocol))?
            .as_ref()
        {
            active.cancel.cancel()
        };
        Ok(())
    }
    pub fn consent(&self, request_id: String, approved: Vec<String>) -> Result<()> {
        self.available()?;
        let mut pending = self
            .state
            .pending_consent
            .lock()
            .map_err(|_| BindingError::from(Error::Protocol))?;
        let allowed = pending
            .get(&request_id)
            .ok_or(Error::Forbidden)
            .map_err(BindingError::from)?;
        let unique = approved.iter().collect::<BTreeSet<_>>();
        if unique.len() != approved.len() || approved.iter().any(|id| !allowed.contains(id)) {
            return Err(Error::Forbidden.into());
        }
        self.state
            .consent
            .lock()
            .map_err(|_| BindingError::from(Error::Protocol))?
            .as_ref()
            .ok_or(Error::Cancelled)
            .map_err(BindingError::from)?
            .send((request_id.clone(), approved))
            .map_err(|_| BindingError::from(Error::Cancelled))?;
        pending.remove(&request_id);
        Ok(())
    }
    pub async fn start_send(&self, text: String, chat_id: Option<String>) -> Result<String> {
        self.available()?;
        // Admission contains no await: foreign cancellation cannot leave an
        // active stream without a receiver/task installed.
        let mut events = self
            .state
            .events
            .try_lock()
            .map_err(|_| BindingError::from(Error::Conflict))?;
        let id = uuid::Uuid::new_v4().to_string();
        let cancel = CancellationToken::new();
        {
            let mut active = self
                .state
                .active
                .lock()
                .map_err(|_| BindingError::from(Error::Protocol))?;
            if active.is_some() {
                return Err(Error::Conflict.into());
            };
            *active = Some(Active {
                id: id.clone(),
                cancel: cancel.clone(),
            });
        }
        let (events_tx, events_rx) = mpsc::channel(8);
        let (consent_tx, consent_rx) = mpsc::unbounded_channel();
        *self
            .state
            .consent
            .lock()
            .map_err(|_| BindingError::from(Error::Protocol))? = Some(consent_tx);
        *events = Some(Events {
            id: id.clone(),
            receiver: events_rx,
        });
        drop(events);
        let state = self.state.clone();
        let text = Zeroizing::new(text);
        tokio::spawn(async move {
            let (tx, mut rx) = mpsc::channel::<StreamUpdate>(1);
            let forward_state = state.clone();
            let forward_events = events_tx.clone();
            let forward_cancel = cancel.clone();
            let forward = tokio::spawn(async move {
                while let Some(update) = rx.recv().await {
                    if let StreamUpdate::Consent { request_id, items } = &update
                        && let Ok(mut pending) = forward_state.pending_consent.lock()
                    {
                        pending.insert(
                            request_id.clone(),
                            items.iter().map(|item| item.id.clone()).collect(),
                        );
                    }
                    let value = json!({"type":"update","update":update});
                    tokio::select! {biased;_=forward_cancel.cancelled()=>break,result=forward_events.send(value)=>if result.is_err(){forward_cancel.cancel();break}}
                }
            });
            let result = {
                let mut client = state.client.lock().await;
                if state.closed.load(Ordering::Acquire) {
                    Err(Error::Cancelled)
                } else {
                    client.set_consent_receiver(consent_rx);
                    client.set_operation_cancel(cancel.clone());
                    client
                        .send_message(chat_id.as_deref(), &text, tx, cancel.clone())
                        .await
                }
            };
            let _ = forward.await;
            if let Ok(mut pending) = state.pending_consent.lock() {
                pending.clear()
            }
            if let Ok(mut consent) = state.consent.lock() {
                consent.take();
            }
            let final_event = match result {
                Ok(chat) => json!({"type":"completed","chat":chat}),
                Err(error) => json!({"type":"error","error":BindingError::from(error)}),
            };
            tokio::select! {biased;_=cancel.cancelled()=>{let _=events_tx.try_send(final_event);},_=events_tx.send(final_event.clone())=>{}}
        });
        Ok(id)
    }
    pub async fn next_event(&self, id: String) -> Result<String> {
        let mut events = self.state.events.lock().await;
        let event_stream = events
            .as_mut()
            .filter(|stream| stream.id == id)
            .ok_or(Error::Conflict)
            .map_err(BindingError::from)?;
        let event = event_stream.receiver.recv().await;
        if event.is_none() {
            *events = None;
            let mut active = self
                .state
                .active
                .lock()
                .map_err(|_| BindingError::from(Error::Protocol))?;
            if active.as_ref().is_some_and(|active| active.id == id) {
                *active = None;
            }
            return Err(Error::Cancelled.into());
        }
        let event = event.ok_or(Error::Cancelled).map_err(BindingError::from)?;
        if event["type"] == "completed" || event["type"] == "error" {
            *events = None;
            let mut active = self
                .state
                .active
                .lock()
                .map_err(|_| BindingError::from(Error::Protocol))?;
            if active.as_ref().is_some_and(|active| active.id == id) {
                *active = None;
            }
        }
        serde_json::to_string(&event).map_err(|_| Error::Protocol.into())
    }
    pub async fn logout(&self) -> Result<()> {
        self.cancel()?;
        let state = self.state.clone();
        self.transaction(async move {
            let mut client = Self::live_client(&state).await?;
            state.identity_epoch.fetch_add(1, Ordering::AcqRel);
            client.logout().await.map_err(BindingError::from)
        })
        .await
    }
    pub async fn close(&self) -> Result<()> {
        self.state.closed.store(true, Ordering::Release);
        self.cancel()?;
        let state = self.state.clone();
        tokio::spawn(async move {
            state.client.lock().await.forget_session();
        })
        .await
        .map_err(|_| BindingError::from(Error::Protocol))?;
        Ok(())
    }
}

