                client.tasks.create(
                    {"title": "synthetic", "model": "forbidden"},
                    filters={"personal": True},
                )
            )
            await rejected(
                client.projects.create(
                    {"name": "synthetic", "provider": "forbidden"},
                    filters={"personal": True},
